+pub fn apply_fee(amount: i64, bps: u32) -> Option<i64> {
+    if bps > 10000 {
+        return None;
+    }
+    let fee = (amount.unsigned_abs() as u128)
+        .checked_mul(u128::from(bps))?
+        .checked_div(10000)?;
+    let signed_fee = if amount < 0 {
+        -(fee as i128)
+    } else {
+        fee as i128
+    };
+    let total = (amount as i128) + signed_fee;
+    if total < i64::MIN as i128 || total > i64::MAX as i128 {
+        return None;
+    }
+    Some(total as i64)
+}
